# Generated by manage.py generate_test_cases.
from django.http import HttpResponse
from django.utils import timezone

from bloomerp.models.tutorial import (
    Tutorial,
    TutorialProgress,
    TutorialRevision,
    TutorialStep,
)
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestTutorialPlaybackView(BloomerpAPIViewTestCase):
    """Tests class `TutorialPlaybackView` from `bloomerp/views/api/tutorials/tutorial_playback.py`."""

    view_name = "tutorial_playback"

    def extendedSetup(self) -> None:
        """Assign a published tutorial to an ordinary learner without author permissions."""
        tutorial = Tutorial.objects.create(
            name="Getting started",
            description='<p onclick="doSomething()">Learn <strong>the basics</strong>.</p>',
        )
        tutorial.assigned_users.add(self.normal_user)
        self.revision = TutorialRevision.objects.create(
            tutorial=tutorial,
            number=1,
            published_at=timezone.now(),
            trigger_route="home",
            auto_start=True,
        )
        self.step = TutorialStep.objects.create(
            revision=self.revision,
            key="welcome",
            sequence=1,
            name="Welcome",
            text="<p>Welcome</p>",
        )

    def mark_started(self, scenario: RequestScenario) -> None:
        """Set up a run already started by this learner."""
        TutorialProgress.objects.create(
            revision=self.revision, user=self.normal_user, started_at=timezone.now()
        )

    def require_different_username(self, scenario: RequestScenario) -> None:
        """Tighten the audience after assignment so the learner can no longer start."""
        tutorial = self.revision.tutorial
        tutorial.user_filter = [
            {
                "connector": "AND",
                "conditions": [
                    {
                        "field_path": "username",
                        "lookup_id": "equals",
                        "value": self.admin_user.get_username(),
                    }
                ],
            }
        ]
        tutorial.save(update_fields=["user_filter"])

    def start_was_recorded(self, response: HttpResponse) -> bool:
        """Verify readable introduction content, real steps, and the recorded launch."""
        result = response.json()
        return (
            result["introduction"] == {
                "name": "Getting started",
                "description": "<p>Learn <strong>the basics</strong>.</p>",
            }
            and [step["id"] for step in result["steps"]] == [str(self.step.pk)]
            and TutorialProgress.objects.filter(
                revision=self.revision,
                user=self.normal_user,
                first_shown_at__isnull=False,
            ).exists()
        )

    def completion_was_recorded(self, response: HttpResponse) -> bool:
        """Verify completion belongs to the authenticated learner and correct step."""
        return TutorialProgress.objects.filter(
            revision=self.revision,
            user=self.normal_user,
            current_step=self.step,
            completed_at__isnull=False,
        ).exists()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover audience rechecks, once-only automatic starts, and completion."""
        start = {"revision_id": str(self.revision.pk), "automatic": True}
        return [
            RequestScenario(
                name="Assigned learner starts and receives published steps",
                method="POST",
                user=self.normal_user,
                data=start,
                content_type="application/json",
                expected=ExpectedResult(response_validators=self.start_was_recorded),
            ),
            RequestScenario(
                name="Unassigned signed-in user cannot retrieve published steps",
                method="POST",
                user=self.admin_user,
                data=start,
                content_type="application/json",
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="An assigned learner must still match the current user filter",
                method="POST",
                user=self.normal_user,
                data=start,
                content_type="application/json",
                prepare=self.require_different_username,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Automatic start is rejected after a previous start",
                method="POST",
                user=self.normal_user,
                data=start,
                content_type="application/json",
                prepare=self.mark_started,
                expected=ExpectedResult(status_code=409),
            ),
            RequestScenario(
                name="Completion is persisted for the learner",
                method="PATCH",
                user=self.normal_user,
                content_type="application/json",
                data={
                    "revision_id": str(self.revision.pk),
                    "step_id": str(self.step.pk),
                    "outcome": "completed",
                },
                prepare=self.mark_started,
                expected=ExpectedResult(
                    status_code=204, response_validators=self.completion_was_recorded
                ),
            ),
        ]
